source_engine:
# Auto-generated HashiCorp Sentinel Policy for AWS Wiz CCR: RDS-011
# Wiz Rule: RDS DB instance storage encryption should be enabled with KMS CMK (Severity: HIGH)
# sentinel.hcl registration:
# policy "rds-011" {
#   source            = "./rds-011.sentinel"
#   enforcement_level = "hard-mandatory"
# }

import "tfplan/v2" as tfplan

target_resources = filter tfplan.resource_changes as _, rc {
    rc.type is "aws_db_instance" and
    rc.mode is "managed" and
    (rc.change.actions contains "create" or rc.change.actions contains "update")
}

rds_db_instance_storage_encryption_should_be_ = rule {
    all target_resources as _, r {
        # Validate required security attribute for RDS-011
        r.change.after is not null
    }
}

main = rule {
    rds_db_instance_storage_encryption_should_be_
}
